  if(typeof STOCK!=='undefined'&&Array.isArray(STOCK))for(const s of STOCK){const k=key(s);if(!stockBy.has(k))stockBy.set(k,s)}

  // Protecao caso o complemento antigo de 01/10 ja tenha sido carregado por outra rota.
